@import "tailwindcss";

@theme inline {
  /* Paper: cream printout stock, warm rather than white */
  --color-paper: oklch(0.975 0.009 85);
  --color-paper-band: oklch(0.85 0.06 85);
  --color-paper-sunk: oklch(0.945 0.012 85);

  /* Ink: warm near-black, tinted toward the paper hue */
  --color-ink: oklch(0.23 0.012 70);
  --color-ink-muted: oklch(0.46 0.015 70);

  /* Ink on dark panels */
  --color-phosphor: oklch(0.79 0.15 78);
  --color-phosphor-dim: oklch(0.78 0.01 80);

  /* Ink two: the second colour of a two colour press */
  --color-orange: oklch(0.55 0.15 42);
  --color-teal: oklch(0.42 0.08 190);
  --color-signal-red: oklch(0.47 0.16 27);

  --color-rule: oklch(0.78 0.014 75);
  --color-rule-strong: oklch(0.23 0.012 70);

  --font-display: var(--font-archivo), system-ui, sans-serif;
  --font-sans: var(--font-archivo), system-ui, sans-serif;
  --font-mono: var(--font-plex-mono), ui-monospace, monospace;

  /* One radius decision: this era is rectangular. Instruments have corners. */
  --radius-sm: 2px;
  --radius-md: 3px;
}

@layer base {
  html {
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
  }

  body {
    background-color: var(--color-paper);
    color: var(--color-ink);
    font-family: var(--font-sans);
  }

  /* Keyboard users get a thick, obvious ring. Never removed. */
  :focus-visible {
    outline: 2px solid var(--color-orange);
    outline-offset: 3px;
  }
}

@layer utilities {
  /* Faint horizontal rule pattern, like lined printout paper */
  .ruled {
    background-image: repeating-linear-gradient(
      to bottom,
      transparent,
      transparent 27px,
      color-mix(in oklch, var(--color-rule) 45%, transparent) 27px,
      color-mix(in oklch, var(--color-rule) 45%, transparent) 28px
    );
  }

  /* Instrument label: small, tracked, monospaced. Used for real field names. */
  .field-label {
    font-family: var(--font-mono);
    font-size: 0.6875rem;
    letter-spacing: 0.1em;
    text-transform: uppercase;
    color: var(--color-ink-muted);
  }

  .tabular {
    font-variant-numeric: tabular-nums;
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}

import type { Metadata } from "next";
