@import "tailwindcss";

@theme inline {
  /* Paper: cream printout stock, warm rather than white */
  --color-paper: oklch(0.975 0.009 85);
  --color-ink: oklch(0.23 0.012 70);
  --color-ink-muted: oklch(0.46 0.015 70);

  /* Instrument panel: dark ink with a phosphor readout */
  --color-phosphor: oklch(0.79 0.15 78);
  --color-phosphor-dim: oklch(0.78 0.01 80);

  /* The second colour of a two colour press */
  --color-orange: oklch(0.55 0.15 42);

  --color-rule: oklch(0.78 0.014 75);

  --font-display: var(--font-archivo), system-ui, sans-serif;
  --font-sans: var(--font-archivo), system-ui, sans-serif;
  --font-mono: var(--font-plex-mono), ui-monospace, monospace;

  /* This era is rectangular: instruments and forms have corners, not pills */
  --radius-sm: 2px;
}

@layer base {
  html {
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
  }

  body {
    background-color: var(--color-paper);
    color: var(--color-ink);
    font-family: var(--font-sans);
  }

  /* Keyboard users get a thick, obvious ring, in the press colour. Never removed. */
  :focus-visible {
    outline: 2px solid var(--color-orange);
    outline-offset: 3px;
  }
}

@layer utilities {
  /* Faint horizontal ruling, like lined printout stock */
  .ruled {
    background-image: repeating-linear-gradient(
      to bottom,
      transparent,
      transparent 31px,
      color-mix(in oklch, var(--color-rule) 42%, transparent) 31px,
      color-mix(in oklch, var(--color-rule) 42%, transparent) 32px
    );
  }

  /* Bureau poster setting: heavy, condensed, tight. Titles only, never body. */
  .poster {
    font-family: var(--font-display);
    font-weight: 800;
    font-stretch: 82%;
    letter-spacing: -0.028em;
    line-height: 0.88;
    text-transform: uppercase;
    text-wrap: balance;
  }

  /* Instrument legend: small, tracked, monospaced, for real field names */
  .legend {
    font-family: var(--font-mono);
    font-size: 0.6875rem;
    font-weight: 500;
    letter-spacing: 0.16em;
    text-transform: uppercase;
  }

  .tabular {
    font-variant-numeric: tabular-nums;
  }

  /* One arrival beat per element, not a blanket scroll reveal */
  .rise {
    animation: rise 520ms cubic-bezier(0.16, 0.84, 0.28, 1) both;
  }

  .rise-2 {
    animation-delay: 70ms;
  }

  .rise-3 {
    animation-delay: 150ms;
  }
}

@keyframes rise {
  from {
    opacity: 0;
    transform: translateY(10px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

@media (prefers-reduced-motion: reduce) {
  .rise,
  .rise-2,
  .rise-3 {
    animation: none;
    opacity: 1;
    transform: none;
  }
}

