input.new_string:
/* Hover is a pointer-device affordance, never the only way to reach anything.
   Declared outside @layer utilities because the compiler drops nested
   at-rules placed inside that layer. Focus is declared after hover so a
   focused field stays white even while the cursor rests on it. */
@media (hover: hover) and (pointer: fine) {
  .field-codes:hover:not(:focus) {
    background-color: color-mix(in oklch, var(--color-paper) 30%, white);
  }

  .control-primary:not([aria-disabled="true"]):hover {
    border-color: var(--color-orange);
    background-color: var(--color-orange);
  }

  .control-primary[aria-disabled="true"]:hover {
    border-color: var(--color-ink-muted);
    background-color: var(--color-ink-muted);
  }
}

.field-codes:focus {
  background-color: white;
}

