import { chromium } from 'playwright';
const b = await chromium.launch();
const p = await b.newPage({ viewport: { width: 1440, height: 900 } });
await p.goto('http://localhost:3207/');
await p.waitForTimeout(700);
// flip aria-disabled off in the DOM to prove the enabled states exist
await p.evaluate(() => document.querySelector('button').removeAttribute('aria-disabled'));
const btn = await p.$('button');
const read = () => btn.evaluate(e => { const c = getComputedStyle(e); return { bg: c.backgroundColor, border: c.borderColor, cursor: c.cursor }; });
console.log('enabledIdle', JSON.stringify(await read()));
await btn.hover(); await p.waitForTimeout(250);
console.log('enabledHover', JSON.stringify(await read()));
await p.mouse.down(); await p.waitForTimeout(200);
console.log('enabledPress', JSON.stringify(await btn.evaluate(e => getComputedStyle(e).transform)));
await p.mouse.up();
await b.close();
EOF
node enabled.mjs 2>&1 | tail -4

