@import "tailwindcss";

@theme inline {
  /* Paper: cream printout stock, warm rather than white */
  --color-paper: oklch(0.975 0.009 85);
  --color-ink: oklch(0.23 0.012 70);
  --color-ink-muted: oklch(0.46 0.015 70);

  /* Instrument panel: dark ink with a phosphor readout */
  --color-phosphor: oklch(0.79 0.15 78);
  --color-phosphor-dim: oklch(0.78 0.01 80);

  /* The second colour of a two colour press */
  --color-orange: oklch(0.55 0.15 42);

  --color-rule: oklch(0.78 0.014 75);
  --color-rule-strong: oklch(0.23 0.012 70);

  --font-display: var(--font-archivo), system-ui, sans-serif;
  --font-sans: var(--font-archivo), system-ui, sans-serif;
  --font-mono: var(--font-plex-mono), ui-monospace, monospace;

  /* This era is rectangular: instruments and forms have corners, not pills */
  --radius-sm: 2px;
}

@layer base {
  html {
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
  }

  body {
    background-color: var(--color-paper);
    color: var(--color-ink);
    font-family: var(--font-sans);
  }

  /* Keyboard users get a thick, obvious ring, in the press colour. Never removed.
     outline-color is deliberately excluded from any transition so the ring paints
     at full contrast on the first frame, not 150ms later. */
  :focus-visible {
    outline: 2px solid var(--color-orange);
    outline-offset: 3px;
    transition: none;
  }

  /* Forced-colours users keep a system ring rather than an authored one that may vanish. */
  @media (forced-colors: active) {
    :focus-visible {
      outline: 3px solid Highlight;
    }
  }
}

@layer utilities {
  /* Faint horizontal ruling, like lined printout stock */
  .ruled {
    background-image: repeating-linear-gradient(
      to bottom,
      transparent,
      transparent 31px,
      color-mix(in oklch, var(--color-rule) 42%, transparent) 31px,
      color-mix(in oklch, var(--color-rule) 42%, transparent) 32px
    );
  }

  /* Bureau poster setting: heavy, condensed, tight. Titles only, never body. */
  .poster {
    font-family: var(--font-display);
    font-weight: 800;
    font-stretch: 82%;
    letter-spacing: -0.028em;
    line-height: 0.88;
    text-transform: uppercase;
    text-wrap: balance;
  }

  /* Instrument legend: small, tracked, monospaced, for real field names */
  .legend {
    font-family: var(--font-mono);
    font-size: 0.6875rem;
    font-weight: 500;
    letter-spacing: 0.16em;
    text-transform: uppercase;
  }

  .tabular {
    font-variant-numeric: tabular-nums;
  }

  /* The paste field: resting and focus. The border stays ink in every
     state, so the field never looks disabled. */
  .field-codes {
    transition: background-color 150ms ease-out;
    touch-action: manipulation;
  }

  /* Primary control. One place defines every state the button can enter:
     resting, hover (pointer devices only), pressed, and unavailable.
     The unavailable state is driven by aria-disabled, not the disabled
     attribute, so the control stays reachable and keeps announcing why. */
  .control-primary {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-height: 2.75rem;
    padding: 0.75rem 1.5rem;
    border: 2px solid var(--color-ink);
    background-color: var(--color-ink);
    color: var(--color-paper);
    font-family: var(--font-mono);
    font-size: 0.875rem;
    font-weight: 500;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    touch-action: manipulation;
    transition:
      background-color 150ms ease-out,
      border-color 150ms ease-out,
      transform 150ms ease-out;
  }

  .control-primary:not([aria-disabled="true"]):active {
    transform: scale(0.97);
  }

  /* Unavailable: recedes without pretending the action worked,
     and still reads at 6.65:1 against the paper. */
  .control-primary[aria-disabled="true"] {
    border-color: var(--color-ink-muted);
    background-color: var(--color-ink-muted);
    cursor: not-allowed;
  }

  /* One arrival beat per element, not a blanket scroll reveal */
  .rise {
    animation: rise 520ms cubic-bezier(0.16, 0.84, 0.28, 1) both;
  }

  .rise-2 {
    animation-delay: 70ms;
  }

  .rise-3 {
    animation-delay: 150ms;
  }
}

@keyframes rise {
  from {
    opacity: 0;
    transform: translateY(10px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

@media (prefers-reduced-motion: reduce) {
  .rise,
  .rise-2,
  .rise-3 {
    animation: none;
    opacity: 1;
    transform: none;
  }

  .field-codes,
  .control-primary {
    transition: none;
  }

  .control-primary:not([aria-disabled="true"]):active {
    transform: none;
  }
}

/* Hover is a pointer-device affordance, never the only way to reach anything.
   Declared outside @layer utilities because the compiler drops nested
   at-rules placed inside that layer. Focus is declared after hover so a
   focused field stays white even while the cursor rests on it. */
@media (hover: hover) and (pointer: fine) {
  .field-codes:hover:not(:focus) {
    background-color: color-mix(in oklch, var(--color-paper) 30%, white);
  }

  .control-primary:not([aria-disabled="true"]):hover {
    border-color: var(--color-orange);
    background-color: var(--color-orange);
  }

  .control-primary[aria-disabled="true"]:hover {
    border-color: var(--color-ink-muted);
    background-color: var(--color-ink-muted);
  }
}

.field-codes:focus {
  background-color: white;
}


