export type FaultCode =
  | "LENGTH"
  | "ILLEGAL_CHARACTER"
  | "LLPIN_SHAPE"
  | "LISTING_INVALID"
  | "INDUSTRY_INVALID"
  | "STATE_UNKNOWN"
  | "YEAR_INVALID"
  | "YEAR_TOO_EARLY"
  | "YEAR_IN_FUTURE"
  | "TYPE_UNKNOWN"
  | "SERIAL_INVALID";

export type Fault = {
  code: FaultCode;
  message: string;
  start: number;
  length: number;
