import { describe, expect, it } from "vitest";
import { decodeLine, decodeList } from "./decode";

// Independent probe written by /check verify. My own inputs, not the author's.
const PIN = { now: new Date("2026-11-26T00:00:00Z") };

function show(label: string, value: unknown) {
  console.log(`\n[${label}]`, JSON.stringify(value, null, 1));
}

describe("independent probe", () => {
  it("AC-1 six blocks on a real CIN", () => {
    const r = decodeLine("L17110MH1973PLC019786", PIN);
    show("AC-1", r);
    expect(r.valid).toBe(true);
  });

  it("AC-2 keeps passing blocks when one fails", () => {
    const r = decodeLine("L17110OD1973PLC019786", PIN);
    show("AC-2", r);
    expect(r.valid).toBe(false);
  });

  it("AC-3 LLPIN carries nothing extra", () => {
    show("AC-3 hyphen", decodeLine("AAA-1234", PIN));
    show("AC-3 bare", decodeLine("AAA1234", PIN));
  });

  it("AC-4 cleaning habits", () => {
    show("AC-4 lower+space", decodeLine("l17110 mh1973 plc019786", PIN));
    show("AC-4 bom", decodeLine("\uFEFFL17110MH1973PLC019786\u00A0", PIN));
  });

  it("AC-5 named faults with positions", () => {
    show("AC-5 short", decodeLine("L17110MH1973PLC01978", PIN));
    show("AC-5 hyphen", decodeLine("L-17110MH1973PLC019786", PIN));
    show("AC-5 junk", decodeLine("L17110MH1973PLC01978!", PIN));
  });

  it("AC-6 tables and near misses", () => {
    show("AC-6 OD", decodeLine("L17110OD1973PLC019786", PIN));
    show("AC-6 AP", decodeLine("L17110AP1973PLC019786", PIN));
    show("AC-6 TG", decodeLine("L17110TG1973PLC019786", PIN));
    show("AC-6 DD", decodeLine("L17110DD1973PLC019786", PIN));
    show("AC-6 CT", decodeLine("L17110CT1973PLC019786", PIN));
    show("AC-6 type", decodeLine("L17110MH1973XYZ019786", PIN));
  });

  it("AC-7 year bounds", () => {
    show("AC-7 future", decodeLine("L17110MH2099PLC019786", PIN));
    show("AC-7 1849", decodeLine("L17110MH1849PLC019786", PIN));
    show("AC-7 1850", decodeLine("L17110MH1850PLC019786", PIN));
    show("AC-7 0000", decodeLine("L17110MH0000PLC019786", PIN));
  });

  it("AC-8 list counts", () => {
    show(
      "AC-8",
      decodeList(
        "L17110MH1973PLC019786\r\n\r\nAAA-1234\nL17110OD1973PLC019786\nL17110MH1973PLC019786\n",
        PIN,
      ).counts,
    );
  });

  it("AC-9 hostile input never throws", () => {
    const nasty = ["", " ", "\u0000", "🙂", "a".repeat(50000), "-".repeat(100), "\n\n", "L17110MH1973PLC01978\u0007"];
    for (const n of nasty) {
      let ok = true;
      try {
        decodeLine(n, PIN);
        decodeList(n, PIN);
      } catch (error) {
        ok = false;
        console.log("THREW on", JSON.stringify(n), String(error));
      }
      expect(ok, `threw on ${JSON.stringify(n).slice(0, 40)}`).toBe(true);
    }
  });
});

