import { describe, expect, it } from "vitest";
import { decodeLine } from "./decode";

const PIN = { now: new Date("2026-11-26T00:00:00Z") };

describe("block position matches cleaned substring", () => {
  it("CIN blocks do slice back out of cleaned", () => {
    const r = decodeLine("L17110MH1973PLC019786", PIN);
    if (!r.valid) throw new Error("expected valid");
    for (const b of r.blocks) {
      const sliced = r.cleaned.slice(b.start, b.start + b.length);
      console.log(`CIN ${b.label}: value=${b.value} slice=${sliced} match=${sliced === b.value}`);
      expect(sliced, `${b.label} slice mismatch`).toBe(b.value);
    }
  });

  it("LLPIN block slices back out of cleaned", () => {
    const r = decodeLine("AAA-1234", PIN);
    if (!r.valid) throw new Error("expected valid");
    for (const b of r.blocks) {
      const sliced = r.cleaned.slice(b.start, b.start + b.length);
      console.log(`LLPIN ${b.label}: value=${b.value} slice=${sliced} match=${sliced === b.value}`);
      expect(sliced, `${b.label} slice mismatch`).toBe(b.value);
    }
  });

  it("two codes on one line fails on length, as specced", () => {
    const r = decodeLine("L17110MH1973PLC019786 AAA-1234", PIN);
    console.log("two codes:", JSON.stringify(r.valid), r.valid ? "" : r.faults[0].code, r.valid ? "" : r.faults[0].message);
    expect(r.valid).toBe(false);
  });

  it("unlisted U passes", () => {
