      const slice = r.cleaned.slice(b.start, b.start + b.length);
      console.log(`${input}: cleaned=${r.cleaned} span=${slice} value=${b.value} len=${b.length}`);
      expect(slice).toBe(r.cleaned);
    }
  });

  it("cin spans still equal their values exactly", () => {
    const r = decodeLine("L17110MH1973PLC019786", PIN);
    if (!r.valid) throw new Error("expected valid");
    for (const b of r.blocks) {
      expect(r.cleaned.slice(b.start, b.start + b.length)).toBe(b.value);
    }
  });
});

