import { describe, expect, it } from "vitest";
import { decodeLine } from "./decode";

const PIN = { now: new Date("2026-11-26T00:00:00Z") };

// Re-run of the probe that caught the original bug, unchanged in intent.
describe("re-verify the defect", () => {
  it("every block span locates real characters in cleaned", () => {
    const inputs = [
      "L17110MH1973PLC019786",
      " l17110 mh1973 plc019786 ",
      "AAA-1234",
      "AAA1234",
      "l17110mh1973plc019786",
      "\uFEFFL17110MH1973PLC019786\u00A0",
    ];
    for (const input of inputs) {
      const r = decodeLine(input, PIN);
      if (!r.valid) throw new Error(`expected valid for ${input}`);
      for (const b of r.blocks) {
        const span = r.cleaned.slice(b.start, b.start + b.length);
        expect(b.start).toBeGreaterThanOrEqual(0);
        expect(b.start + b.length).toBeLessThanOrEqual(r.cleaned.length);
        expect(span.length, `${input} ${b.label} empty span`).toBeGreaterThan(0);
        console.log(
          `${input.slice(0, 24).padEnd(24)} ${b.label.padEnd(9)} span="${span}" value="${b.value}"`,
        );
      }
    }
  });

  it("highlighting the llpin span shows the whole identifier", () => {
    const r = decodeLine("AAA-1234", PIN);
    if (!r.valid) throw new Error("expected valid");
    const b = r.blocks[0];
    expect(r.cleaned.slice(b.start, b.start + b.length)).toBe("AAA-1234");
  });
});

import { describe, expect, it } from "vitest";
import { decodeLine, decodeList } from "./decode";
import { STATES } from "./reference/states";
import { COMPANY_TYPES } from "./reference/company-types";

// /check verify probe. Independent inputs, driven against the real module.
const PIN = { now: new Date("2026-11-26T00:00:00Z") };
const log = (label: string, value: unknown) =>
  console.log(`[${label}]`, typeof value === "string" ? value : JSON.stringify(value));

function spanOk(reading: ReturnType<typeof decodeLine>): boolean {
  if (!reading.valid) return true;
  return reading.blocks.every((b) => {
    const span = reading.cleaned.slice(b.start, b.start + b.length);
    return (
      b.start >= 0 &&
      b.length > 0 &&
      b.start + b.length <= reading.cleaned.length &&
      span.length === b.length
    );
  });
}

describe("AC-1 blocks and spans", () => {
  it("real CIN, every span locates real characters", () => {
    const r = decodeLine("L17110MH1973PLC019786", PIN);
    if (!r.valid) throw new Error("expected valid");
    for (const b of r.blocks) {
      const span = r.cleaned.slice(b.start, b.start + b.length);
      log(`AC-1 ${b.label}`, `span="${span}" value="${b.value}" eq=${span === b.value}`);
      expect(span).toBe(b.value);
    }
    expect(r.blocks.map((b) => b.label)).toEqual([
      "Listing", "Industry", "State", "Year", "Type", "Serial",
    ]);
  });

  it("tables are the sizes the spec claims, counted at runtime", () => {
    log("states", `${STATES.length} codes`);
    log("types", `${COMPANY_TYPES.length} codes`);
    expect(STATES).toHaveLength(36);
    expect(COMPANY_TYPES).toHaveLength(12);
  });

  it("no duplicate codes in either table", () => {
    const s = new Set(STATES.map((x) => x.code));
    const t = new Set(COMPANY_TYPES.map((x) => x.code));
    expect(s.size).toBe(STATES.length);
    expect(t.size).toBe(COMPANY_TYPES.length);
  });

  it("every state and type code is accepted in a real CIN", () => {
    for (const st of STATES) {
      const r = decodeLine(`U17110${st.code}1999PTC000001`, PIN);
      expect(r.valid, `state ${st.code} rejected`).toBe(true);
    }
    for (const ty of COMPANY_TYPES) {
      const r = decodeLine(`U17110MH1999${ty.code}000001`, PIN);
      expect(r.valid, `type ${ty.code} rejected`).toBe(true);
    }
    log("AC-1 all codes", "36 states and 12 types all accepted");
  });
});

describe("AC-3 LLPIN, the previously broken span", () => {
  it("hyphen present: span is the whole line, value has no hyphen", () => {
    const r = decodeLine("AAA-1234", PIN);
    if (!r.valid) throw new Error("expected valid");
    const b = r.blocks[0];
    const span = r.cleaned.slice(b.start, b.start + b.length);
    log("AC-3 with hyphen", `cleaned=${r.cleaned} span="${span}" value="${b.value}"`);
    expect(span).toBe("AAA-1234");
    expect(b.value).toBe("AAA1234");
    expect(b.start).toBe(0);
    expect(b.length).toBe(r.cleaned.length);
  });

  it("no hyphen: span equals value", () => {
    const r = decodeLine("AAA1234", PIN);
    if (!r.valid) throw new Error("expected valid");
    const b = r.blocks[0];
    const span = r.cleaned.slice(b.start, b.start + b.length);
    log("AC-3 no hyphen", `cleaned=${r.cleaned} span="${span}" value="${b.value}"`);
    expect(span).toBe(b.value);
  });

  it("lower case with hyphen still spans correctly", () => {
    const r = decodeLine("aAa-1234", PIN);
    if (!r.valid) throw new Error("expected valid");
    const b = r.blocks[0];
    log("AC-3 lower", `cleaned=${r.cleaned} span="${r.cleaned.slice(b.start, b.start + b.length)}"`);
    expect(r.cleaned.slice(b.start, b.start + b.length)).toBe(r.cleaned);
  });

  it("double hyphen and stray hyphen are rejected, not accepted", () => {
    for (const bad of ["AAA--1234", "AAA-12-34", "-AAA1234", "AAA1234-"]) {
      const r = decodeLine(bad, PIN);
      log(`AC-3 bad ${bad}`, r.valid ? "ACCEPTED (wrong)" : "rejected");
      expect(r.valid, `${bad} should be rejected`).toBe(false);
    }
  });
});

describe("AC-2 and AC-5 faults, collected and positioned", () => {
  it("several bad blocks all reported at once", () => {
    const r = decodeLine("Z17110ZZ1999XYZ000001", PIN);
    if (r.valid) throw new Error("expected invalid");
    log("AC-2 codes", r.faults.map((f) => f.code).join(", "));
    log("AC-2 positions", r.faults.map((f) => `${f.code}@${f.start}+${f.length}`).join(" "));
    expect(r.faults.length).toBeGreaterThan(1);
    for (const f of r.faults) {
      expect(f.start).toBeGreaterThanOrEqual(0);
      expect(f.start + f.length).toBeLessThanOrEqual(r.cleaned.length);
    }
  });

  it("faults stay inside the cleaned string for every bad input I can think of", () => {
    const bad = [
      "", "-", "--", "!!!", "L", "L17110", "L17110MH", "L17110MH1973",
      "L17110MH1973PLC", "0".repeat(21), "L".repeat(21),
      "L17110MH1973PLC01978", "L17110MH1973PLC0197866",
      "L17110MH1973PLC01978!", "   ", "\t\t", "😀😀😀", "a".repeat(10000),
    ];
    for (const input of bad) {
      const r = decodeLine(input, PIN);
      for (const f of r.valid ? [] : r.faults) {
        expect(f.start, `start for ${JSON.stringify(input).slice(0, 20)}`).toBeGreaterThanOrEqual(0);
        expect(
          f.start + f.length,
          `end for ${JSON.stringify(input).slice(0, 20)}`,
        ).toBeLessThanOrEqual(r.cleaned.length);
      }
    }
    log("AC-5 bounds", `${bad.length} hostile inputs, every fault inside cleaned`);
  });
});

describe("AC-6 tables and near misses", () => {
  it("OD suggests OR, and the suggestion is a real state", () => {
    const r = decodeLine("L17110OD1973PLC019786", PIN);
    if (r.valid) throw new Error("expected invalid");
    const f = r.faults[0];
    log("AC-6 OD", `${f.code} suggestion=${f.suggestion}`);
    expect(f.code).toBe("STATE_UNKNOWN");
    expect(f.suggestion).toBe("OR");
    expect(STATES.some((s) => s.code === f.suggestion)).toBe(true);
  });

  it("AP, DD, DN valid with notes; TG and MH valid with none", () => {
    for (const [code, expectNote] of [["AP", true], ["DD", true], ["DN", true], ["TG", false], ["MH", false]] as const) {
      const r = decodeLine(`L17110${code}1973PLC019786`, PIN);
      if (!r.valid) throw new Error(`${code} should be valid`);
      log(`AC-6 ${code}`, `notes=${r.notes.length}`);
      expect(r.notes.length > 0, `${code} note`).toBe(expectNote);
    }
  });

  it("legacy codes fail and the message says to check with MCA", () => {
    for (const code of ["CT", "UA", "TS", "OD", "ZZ"]) {
      const r = decodeLine(`L17110${code}1973PLC019786`, PIN);
      if (r.valid) throw new Error(`${code} should not be valid`);
      log(`AC-6 legacy ${code}`, r.faults[0].message);
      expect(r.faults[0].code).toBe("STATE_UNKNOWN");
    }
  });
});

describe("AC-7 year boundaries", () => {
  it("exact edges with a pinned clock", () => {
    const cases: Array<[string, boolean]> = [
      ["1849", false], ["1850", true], ["1900", true], ["2025", true], ["2026", true], ["2027", false], ["9999", false],
    ];
    for (const [year, shouldPass] of cases) {
      const r = decodeLine(`L17110MH${year}PLC019786`, PIN);
      log(`AC-7 ${year}`, r.valid ? "valid" : (r as { faults: { code: string }[] }).faults[0].code);
      expect(r.valid, `year ${year}`).toBe(shouldPass);
    }
  });
});

describe("AC-8 list behaviour", () => {
  it("counts reconcile across all newline styles", () => {
    for (const nl of ["\n", "\r\n", "\r"]) {
      const text = ["L17110MH1973PLC019786", "", "AAA-1234", "L17110OD1973PLC019786", "L17110MH1973PLC019786"].join(nl) + nl;
      const list = decodeList(text, PIN);
      log(`AC-8 ${JSON.stringify(nl)}`, list.counts);
      expect(list.counts.read).toBe(4);
      expect(list.counts.valid + list.counts.invalid).toBe(list.counts.read);
      expect(list.rows).toHaveLength(4);
    }
  });

  it("every row keeps a valid span", () => {
    const list = decodeList("l17110mh1973plc019786\nAAA-1234\nL17110OD1973PLC019786", PIN);
    for (const row of list.rows) {
      expect(spanOk(row)).toBe(true);
    }
    log("AC-8 spans", "all rows span correctly");
  });
});

describe("AC-9 purity", () => {
  it("never throws and is deterministic", () => {
    const nasty = ["", " ", "\u0000", "\u0007", "\uFEFF", "🙂", "a".repeat(50000), "-".repeat(200), "\n\n\n"];
    for (const n of nasty) {
      expect(() => decodeLine(n, PIN)).not.toThrow();
      expect(() => decodeList(n, PIN)).not.toThrow();
    }
    expect(decodeLine("AAA-1234", PIN)).toEqual(decodeLine("AAA-1234", PIN));
    log("AC-9", `${nasty.length} hostile inputs, no throw`);
  });
});

