import { describe, it } from "vitest";
import { decodeLine } from "./decode";

const PIN = { now: new Date("2026-11-26") };

describe("probe for the spec decision", () => {
  it("7 character junk routes to the LLPIN path", () => {
    const r = decodeLine("1234567", PIN);
    console.log("1234567 ->", r.kind, "valid:", r.valid, "blocks:", r.valid ? r.blocks.length : "none");
    if (!r.valid) console.log("  faults:", r.faults.map((f) => f.code).join(","));
    console.log("  has blocks property:", "blocks" in r);
  });

  it("AAA-1234 is a valid pinned example", () => {
    const r = decodeLine("AAA-1234", PIN);
    console.log("AAA-1234 ->", r.kind, "valid:", r.valid);
  });

  it("how much text is one CIN card", () => {
    const r = decodeLine("L17110MH1973PLC019786", PIN);
    if (!r.valid) throw new Error("expected valid");
    const lines = 1 + 1 + r.blocks.length + r.blocks.length;
    console.log(`one card: ${r.blocks.length} blocks, each label+value+meaning = ~${lines} lines`);
    console.log(`ten cards = ~${lines * 10} lines`);
  });
});

