import type { Reading } from "@/lib/types";

export function ResultOutcome({ reading }: { reading: Reading }) {
  const pass = reading.valid;
  return (
    <p className={pass ? "stamp stamp-pass" : "stamp stamp-fail"}>
      <span>{pass ? "Valid" : "Not valid"}</span>
      {reading.kind === "llpin" ? (
        <span className="stamp-kind">LLP</span>
      ) : null}
    </p>
  );
}

import type { Fault } from "../types";

export type Segment = {
  text: string;
  fault: boolean;
};

type Range = {
  start: number;
  end: number;
};

function toRanges(cleaned: string, faults: Fault[]): Range[] {
  const ranges: Range[] = [];

  for (const fault of faults) {
    const start = Math.max(0, Math.min(fault.start, cleaned.length));
    const end = Math.max(start, Math.min(fault.start + fault.length, cleaned.length));
    if (end > start) {
      ranges.push({ start, end });
    }
  }

  return ranges.sort((a, b) => a.start - b.start);
}

function merge(ranges: Range[]): Range[] {
  const merged: Range[] = [];

  for (const range of ranges) {
    const last = merged[merged.length - 1];
    if (last && range.start <= last.end) {
      last.end = Math.max(last.end, range.end);
    } else {
      merged.push({ ...range });
    }
  }

  return merged;
}

export function markSpans(cleaned: string, faults: Fault[]): Segment[] {
  const ranges = merge(toRanges(cleaned, faults));
  if (ranges.length === 0) {
    return cleaned.length === 0 ? [] : [{ text: cleaned, fault: false }];
  }

  const segments: Segment[] = [];
  let cursor = 0;

  for (const range of ranges) {
    if (range.start > cursor) {
      segments.push({ text: cleaned.slice(cursor, range.start), fault: false });
    }
    segments.push({ text: cleaned.slice(range.start, range.end), fault: true });
    cursor = range.end;
  }

  if (cursor < cleaned.length) {
    segments.push({ text: cleaned.slice(cursor), fault: false });
  }

  return segments;
}

import type { Fault } from "@/lib/types";
import { markSpans } from "@/lib/results/spans";

export function ResultCode({
  cleaned,
  faults = [],
}: {
  cleaned: string;
  faults?: Fault[];
}) {
  const segments = markSpans(cleaned, faults);

  return (
    <p className="break-all font-mono text-base leading-[1.5] tracking-wide text-ink">
      {segments.map((segment, index) =>
        segment.fault ? (
          <mark key={index} className="fault-mark">
            {segment.text}
          </mark>
        ) : (
          <span key={index}>{segment.text}</span>
        ),
      )}
    </p>
  );
}

import type { Reading } from "@/lib/types";

const CIN_ORDER = ["Listing", "Industry", "State", "Year", "Type", "Serial"];

function order(blocks: Reading["blocks"]) {
  return [...blocks].sort(
    (a, b) => CIN_ORDER.indexOf(a.label) - CIN_ORDER.indexOf(b.label),
  );
}

export function ResultBlocks({ reading }: { reading: Reading }) {
  if (!("blocks" in reading) || reading.blocks.length === 0) {
    return null;
  }

  const isLlp = reading.kind === "llpin";
  const blocks = isLlp ? reading.blocks : order(reading.blocks);

  return (
    <dl className="grid gap-x-6 gap-y-4 sm:grid-cols-2">
      {blocks.map((block) => (
        <div key={block.label} className="flex flex-col gap-1">
          <dt className="legend text-ink-muted">{block.label}</dt>
          <dd className="font-mono text-base tabular text-ink">{block.value}</dd>
          <dd className="text-sm leading-snug text-ink-muted">
            {block.meaning}
          </dd>
        </div>
      ))}
    </dl>
  );
}

import type { Reading } from "@/lib/types";
import { plainSentence } from "@/lib/results/summary";

export function ResultReading({ reading }: { reading: Reading }) {
  const faults = reading.valid ? [] : reading.faults;
  const notes = reading.valid ? reading.notes : [];

  return (
    <div className="flex flex-col gap-4">
      <p className="max-w-[60ch] text-base leading-relaxed text-ink">
        {plainSentence(reading)}
      </p>

      {reading.input !== reading.cleaned ? (
        <p className="font-mono text-xs leading-relaxed text-ink-muted">
          Pasted as {reading.input}
        </p>
      ) : null}

      {faults.length > 0 ? (
        <ul className="flex flex-col gap-3 border-s-2 border-orange ps-4">
          {faults.map((fault, index) => (
            <li key={`${fault.code}-${index}`} className="flex flex-col gap-1">
              <p className="text-sm leading-relaxed text-ink">{fault.message}</p>
              {fault.suggestion ? (
                <p className="text-sm leading-relaxed text-ink-muted">
                  {fault.suggestion}
                </p>
              ) : null}
            </li>
          ))}
        </ul>
      ) : null}

      {notes.length > 0 ? (
        <ul className="flex flex-col gap-2">
          {notes.map((note, index) => (
            <li
              key={index}
              className="max-w-[60ch] text-sm leading-relaxed text-ink-muted"
            >
              {note}
            </li>
          ))}
        </ul>
      ) : null}
    </div>
  );
}

