import type { Reading } from "@/lib/types";
import { ResultCode } from "./result-code";
import { ResultOutcome } from "./outcome";
import { ResultBlocks } from "./result-blocks";
import { ResultReading } from "./result-reading";

export function ResultCard({ reading }: { reading: Reading }) {
  const faults = reading.valid ? [] : reading.faults;

  return (
    <article className="docket flex flex-col gap-5 px-5 py-5 sm:px-6 sm:py-6">
      <div className="flex flex-wrap items-center justify-between gap-x-4 gap-y-2">
        <ResultOutcome reading={reading} />
        <p className="legend text-ink-muted">
          {reading.kind === "cin" ? "CIN" : "LLPIN"}
        </p>
      </div>

      <ResultCode cleaned={reading.cleaned} faults={faults} />
      <ResultReading reading={reading} />

      <div className="border-t border-rule pt-4">
        <ResultBlocks reading={reading} />
      </div>
    </article>
  );
}

import type { Reading } from "../types";

export function blockByLabel(
  reading: Reading,
  label: string,
): { value: string; meaning: string } | undefined {
  if (!("blocks" in reading)) {
    return undefined;
  }
  return reading.blocks.find((block) => block.label === label);
}

import type { Reading } from "../types";
import { blockByLabel } from "./blocks";

function lowerFirst(text: string): string {
  return text.length === 0 ? text : text.charAt(0).toLowerCase() + text.slice(1);
}

export function plainSentence(reading: Reading): string {
  if (reading.kind === "llpin") {
    return reading.valid
      ? "An LLP registration number. It identifies the LLP and nothing more."
      : "This one is not a valid LLP registration number.";
  }

  if (!reading.valid) {
    return "This one needs a fix before it can be read.";
  }

  const listing = blockByLabel(reading, "Listing")?.value === "U" ? "unlisted" : "listed";
  const type = lowerFirst(blockByLabel(reading, "Type")?.meaning ?? "company");
  const state = blockByLabel(reading, "State")?.meaning ?? "an unknown state";
  const year = blockByLabel(reading, "Year")?.value ?? "an unknown year";
  const article = listing === "unlisted" ? "An" : "A";

  return `${article} ${listing} ${type}, registered in ${state} in ${year}.`;
}

import type { Reading } from "@/lib/types";
import { blockByLabel } from "@/lib/results/blocks";
import { ResultCode } from "./result-code";
import { ResultOutcome } from "./outcome";
import { ResultBlocks } from "./result-blocks";
import { ResultReading } from "./result-reading";

function Cell({
  label,
  value,
  meaning,
}: {
  label: string;
  value: string;
  meaning: string;
}) {
  return (
