"use client";

import { useEffect, useMemo, useState } from "react";
import { decodeList } from "@/lib/decode";
import type { Reading } from "@/lib/types";
import { countReadings, totalsSentence } from "@/lib/results/counts";
import { DEBOUNCE_MS } from "@/lib/results/layout";
import { EmptyState } from "./results/empty-state";
import { Results } from "./results/results";

export function Checker() {
  const [text, setText] = useState("");
  const [atRest, setAtRest] = useState("");

  useEffect(() => {
    if (text === atRest) {
      return;
    }
    const timer = setTimeout(() => setAtRest(text), DEBOUNCE_MS);
    return () => clearTimeout(timer);
  }, [text, atRest]);

  const readings = useMemo<Reading[]>(() => {
    if (atRest.trim().length === 0) {
      return [];
    }
    return decodeList(atRest).rows;
  }, [atRest]);

  const counts = countReadings(readings);

  return (
    <section
      id="checker"
      aria-labelledby="checker-heading"
      className="mt-14 scroll-mt-6 border-y-2 border-ink py-10 sm:mt-20 sm:py-14"
    >
      <h2 id="checker-heading" className="sr-only">
        Check a list of identifiers
      </h2>

      <div className="grid gap-x-10 gap-y-8 sm:grid-cols-[1fr_auto] sm:items-end">
        <div>
          <label htmlFor="codes" className="legend text-ink-muted">
            Paste your identifiers
          </label>
          <p
            id="codes-hint"
            className="mt-2 max-w-[52ch] text-sm leading-relaxed text-ink-muted"
          >
            One per line. Spaces and lower case are cleaned up for you.
          </p>
        </div>
        <p className="font-mono text-xs text-ink-muted">
          A CIN is 21 characters. An LLPIN looks like AAA-1234.
        </p>
      </div>

      <div className="mt-6">
        <textarea
          id="codes"
          name="codes"
          rows={7}
          value={text}
          onChange={(event) => setText(event.target.value)}
          spellCheck={false}
          autoComplete="off"
          autoCapitalize="characters"
          aria-describedby="codes-hint"
          placeholder={"L17110MH1973PLC019786\nU72900KA2010PTC086596\nAAA-1234"}
          className="field-codes ruled block w-full resize-y border border-ink bg-white/70 px-4 py-3 font-mono text-base leading-[2] tracking-wide text-ink placeholder:text-ink-muted"
        />
      </div>

      <div
        role="status"
        aria-live="polite"
        aria-atomic="true"
        className="sr-only"
      >
        {totalsSentence(counts)}
      </div>

      <dl className="mt-10 grid grid-cols-2 gap-x-6 gap-y-6 border-t border-rule pt-6 sm:grid-cols-4">
        {[
          { term: "Read", value: counts.read },
          { term: "Valid", value: counts.valid },
          { term: "Not valid", value: counts.invalid },
          { term: "LLP", value: counts.llp },
        ].map((reading) => (
          <div key={reading.term} className="flex flex-col gap-2">
            <dt className="legend text-ink-muted">{reading.term}</dt>
            <dd className="font-mono text-2xl tabular text-ink sm:text-3xl">
              <span key={reading.value} className="reading reading-write">
                {reading.value}
              </span>
            </dd>
          </div>
        ))}
      </dl>

      {readings.length === 0 ? (
        <EmptyState onFill={setText} />
      ) : (
        <Results readings={readings} />
      )}
    </section>
  );
}

import { describe, expect, it } from "vitest";
import { decodeLine } from "../decode";
import { markSpans } from "./spans";

const PIN = { now: new Date("2026-11-26") };

function marked(cleaned: string, faults: Parameters<typeof markSpans>[1]) {
  return markSpans(cleaned, faults)
    .filter((segment) => segment.fault)
    .map((segment) => segment.text);
}

describe("markSpans", () => {
  it("returns the whole string unmarked when there are no faults", () => {
    const segments = markSpans("L17110MH1973PLC019786", []);
    expect(segments).toEqual([{ text: "L17110MH1973PLC019786", fault: false }]);
  });

  it("marks exactly the failing characters of a whole string fault", () => {
    const reading = decodeLine("nonsense", PIN);
    if (reading.valid) throw new Error("expected invalid");
    expect(marked(reading.cleaned, reading.faults)).toEqual([reading.cleaned]);
  });

  it("marks only the bad state block, not the year or serial", () => {
    const reading = decodeLine("L17110ZZ1973PLC019786", PIN);
    if (reading.valid) throw new Error("expected invalid");
    expect(marked(reading.cleaned, reading.faults)).toEqual(["ZZ"]);
  });

  it("marks only the bad listing character", () => {
    const reading = decodeLine("X17110MH1973PLC019786", PIN);
    if (reading.valid) throw new Error("expected invalid");
    expect(marked(reading.cleaned, reading.faults)).toEqual(["X"]);
  });

  it("rebuilds the original string exactly from its segments", () => {
    for (const line of [
      "L17110ZZ1973PLC019786",
      "X17110MH1973PLC019786",
      "nonsense",
      "L17110MH1973PLC019786",
      "AAA-1234",
      "1234567",
    ]) {
      const reading = decodeLine(line, PIN);
      const faults = reading.valid ? [] : reading.faults;
      const rebuilt = markSpans(reading.cleaned, faults)
        .map((segment) => segment.text)
        .join("");
      expect(rebuilt).toBe(reading.cleaned);
    }
  });

  it("merges overlapping faults into one mark rather than nesting", () => {
    const segments = markSpans("ABCDEF", [
      { code: "LENGTH", message: "", start: 1, length: 3 },
      { code: "LENGTH", message: "", start: 2, length: 3 },
    ]);
    expect(segments).toEqual([
      { text: "A", fault: false },
      { text: "BCDE", fault: true },
      { text: "F", fault: false },
    ]);
  });

  it("clamps a span that runs past the end of the string", () => {
    const segments = markSpans("ABC", [
      { code: "LENGTH", message: "", start: 1, length: 99 },
    ]);
    expect(segments).toEqual([
      { text: "A", fault: false },
      { text: "BC", fault: true },
    ]);
  });

  it("marks the hyphen in a CIN at its real position", () => {
    const reading = decodeLine("L17110MH1973PLC019786 AAA-1234", PIN);
    if (reading.valid) throw new Error("expected invalid");
    const located = reading.faults.find(
      (fault) => fault.code === "ILLEGAL_CHARACTER",
    );
    expect(located?.start).toBe(22);
    expect(reading.cleaned.slice(22, 23)).toBe("");
  });
});

